// Mutation check for the dev tests: each mutant breaks one behaviour in a file of the web folder
// it is given (a COPY: never the real web/), or in two files when one guards the other, runs the
// test script that guards it (the native harness, the bridge 4 harness, the unit checks, the upload
// harness, the static checks, parts of the UI smoke test, at the phone size unless the mutant
// names another, or parts of a gesture check, web/dev/gestures-<name>.mjs),
// expects the named check(s) to FAIL, then puts the original bytes back from a backup copy taken
// first and checks them byte for byte.
// Usage: node <copy>/dev/mutants.mjs <copy of web> [--ui | --ui-only] [--gestures | --gestures-only] [--only <name substring>[|<another>...]]
//   (exit 1 if a mutant survives or a restore differs; --ui adds the UI smoke mutants, --gestures
//   the gesture mutants, both slower)
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

