const uiOnly = process.argv.includes('--ui-only');
const withUi = uiOnly || process.argv.includes('--ui');
const gesturesOnly = process.argv.includes('--gestures-only');
const withGestures = gesturesOnly || process.argv.includes('--gestures');
const onlyAt = process.argv.indexOf('--only');
const only = onlyAt > 0 ? process.argv[onlyAt + 1].split('|') : null;
const scripts = {
  harness: path.join(web, 'dev', 'native-harness.mjs'),
  unit: path.join(web, 'dev', 'unit.mjs'),
  upload: path.join(web, 'dev', 'upload-harness.mjs'),
  bridge4: path.join(web, 'dev', 'bridge4-harness.mjs'),
};
const uiOut = path.join(web, '..', 'ui-mutant-run');
const gestureOut = path.join(web, '..', 'gesture-mutant-run');

