function runTest(m) {
  if (m.runner === 'check') {
    const logFile = path.join(web, '..', 'check-mutant.log');
    const r = spawnSync(process.execPath, [path.join(web, 'dev', 'check.mjs'), web, logFile], { encoding: 'utf8', timeout: 300000 });
    let lines = [];
    try {
      lines = fs.readFileSync(logFile, 'utf8').split(/\r?\n/);
    } catch {
      /* no log */
    }
    const failed = lines.filter((l) => /^(NAMED|TOO NEW|BANNED|OLD NAME|FAIL|MISSING|NO EXPORT|LAYOUT)/.test(l));
    return { status: r.status, failed, killed: m.expect.every((e) => failed.some((f) => f.includes(e))) };
  }
  if (m.gestures) {
    fs.rmSync(gestureOut, { recursive: true, force: true });
    fs.mkdirSync(gestureOut, { recursive: true });
    const r = spawnSync(process.execPath, [path.join(web, 'dev', `gestures-${m.gestures}.mjs`), gestureOut, ...(m.args || [])], { encoding: 'utf8', timeout: 590000 });
    const failed = (r.stdout || '').split('\n').filter((l) => l.startsWith('FAIL')).map((l) => l.slice(5));
    return { status: r.status, failed, killed: m.expect.every((e) => failed.some((f) => f.includes(e))) };
  }
  if (!m.ui) {
    const r = spawnSync(process.execPath, [scripts[m.runner || 'harness'], web], { encoding: 'utf8', timeout: 300000 });
    const failed = (r.stdout || '').split('\n').filter((l) => l.startsWith('FAIL')).map((l) => l.slice(5).split(' :: ')[0]);
    return { status: r.status, failed, killed: m.expect.every((e) => failed.includes(e)) };
  }
  fs.rmSync(uiOut, { recursive: true, force: true });
  fs.mkdirSync(uiOut, { recursive: true });
  const r = spawnSync(process.execPath, [path.join(web, 'dev', 'ui-smoke.mjs'), uiOut], { encoding: 'utf8', timeout: 590000, env: { ...process.env, MPFY_SMOKE_ONLY: m.ui, MPFY_SMOKE_VP: m.vp || '360' } });
  let lines = [];
  try {
    lines = fs.readFileSync(path.join(uiOut, 'ui-smoke.log'), 'utf8').split('\n');
  } catch {
    /* no log */
  }
  const failed = lines.filter((l) => l.startsWith('FAIL')).map((l) => l.slice(5));
  return { status: r.status, failed, killed: m.expect.every((e) => failed.some((f) => f.includes(e))) };
}

let bad = 0;
const list = MUTANTS.filter((m) => (withUi || !m.ui) && (!uiOnly || m.ui) && (withGestures || !m.gestures) && (!gesturesOnly || m.gestures) && (!only || only.some((o) => m.name.includes(o))));
for (const m of list) {
  // One edit, or several in different files (also): each file backed up first, restored from it.
  const edits = [{ file: m.file, from: m.from, to: m.to }, ...(m.also || [])].map((e) => ({ ...e, path: path.join(web, e.file) }));
  // One backup per file, even when several edits touch the same one.
  const files = [...new Set(edits.map((e) => e.path))].map((p) => ({ path: p, backup: `${p}.mutant-backup` }));
  for (const f of files) fs.copyFileSync(f.path, f.backup);
  const missing = edits.filter((e) => fs.readFileSync(e.path, 'utf8').split(e.from).length !== 2);
  if (missing.length) {
    console.log(`== ${m.name}: anchor not found exactly once in ${missing.map((e) => e.file).join(', ')}`);
    bad++;
    for (const f of files) fs.rmSync(f.backup);
    continue;
  }
  for (const e of edits) fs.writeFileSync(e.path, fs.readFileSync(e.path, 'utf8').replace(e.from, () => e.to));
  let res;
  try {
    res = runTest(m);
  } finally {
    for (const f of files) fs.copyFileSync(f.backup, f.path); // restore from the copy, never from git
  }
  const same = files.every((f) => Buffer.compare(fs.readFileSync(f.path), fs.readFileSync(f.backup)) === 0);
  for (const f of files) fs.rmSync(f.backup);
  console.log(`== mutant: ${m.name} (${edits.map((e) => e.file).join(' + ')}${m.ui ? `, ui ${m.ui}` : ''}${m.gestures ? `, gestures-${m.gestures} ${(m.args || []).join(' ')}` : ''})`);
  for (const l of res.failed) console.log(`   FAIL ${l}`);
  console.log(`   ${res.killed ? 'KILLED' : 'SURVIVED'} (exit ${res.status}); restored byte for byte: ${same ? 'yes' : 'NO'}`);
  if (!res.killed || !same) bad++;
}
for (const [name, script] of Object.entries(scripts)) {
  const r = spawnSync(process.execPath, [script, web], { encoding: 'utf8', timeout: 300000 });
  console.log(`== original code again: ${name} exit ${r.status}, ${(r.stdout.match(/^OK/gm) || []).length} OK`);
  if (r.status !== 0) bad++;
}
console.log(`mutants=${list.length} bad=${bad}`);
process.exit(bad ? 1 : 0);
